SELECT  FROM combination_review_run r
INNER JOIN combination_review c ON c.id = r.review_id
WHERE r.id = #{runId} AND r.review_id = #{reviewId} AND c.owner_account_id = #{ownerId}

SELECT  FROM combination_review_run r
INNER JOIN combination_review c ON c.id = r.review_id
WHERE r.review_id = #{reviewId} AND c.owner_account_id = #{ownerId}
AND r.id < #{beforeId}
ORDER BY r.id DESC LIMIT #{limit}
